	private void upgradeDir(File dir)
    {

		if ("upgrades".equals(dir.getName())) {
			return; // ignore the special upgrade directory
		}

		foreach (File f in dir.listFiles()) {
			if (f.isFile() && f.getName().endsWith(".gzf")) {
				Msg.info(this, "Processing " + f.getName() + " ...");
				if (upgradeProgramArchive(f)) {
					Msg.info(this, "   program upgraded!");
				}
			}
			else if (f.isDirectory()) {
				upgradeDir(f);
			}
		}
	}

	private bool upgradeProgramArchive(File gzf)
    {

		PackedDatabase db = PackedDatabase.getPackedDatabase(gzf, TaskMonitor.DUMMY);
		DBHandle dbh = null;
		ProgramDB p = null;
		try {
			dbh = db.openForUpdate(monitor);

			if (dbh.getTable("Program") == null) {
				return false;
			}

			try {
				p = new ProgramDB(dbh, OpenMode.UPDATE, monitor, this);
				return false;
			}
			catch (LanguageNotFoundException e) {
				Msg.error(this, e.getMessage());
				return false;
			}
			catch (VersionException e) {
				if (!e.isUpgradable()) {
					Msg.error(this, e.getMessage());
					return false;
				}
			}
			finally {
				dbh.close();
			}

			dbh = db.openForUpdate(monitor);
			p = new ProgramDB(dbh, OpenMode.UPGRADE, monitor, this);

			if (!p.isChanged()) {
				return false;
			}

			p.save(null, monitor);
		}
		finally {
			if (p != null) {
				p.release(this);
			}
			if (dbh != null) {
				dbh.close();
			}
			db.dispose();
		}

		return true;
	}

}
